def transforms(S):
 out=[]
 for k in range(4):
  s=set()
  for r,c in S:
   for _ in range(k): r,c=c,-r
   s.add((r,c))
  for refl in (False,True):
   z={(r,-c if refl else c) for r,c in s}; mr=min(r for r,c in z); mc=min(c for r,c in z)
   out.append({(r-mr,c-mc) for r,c in z})
 return out
